package com.bank.fraudcfg;

import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.StringDeserializer;
import java.time.Duration;
import java.util.*;
import java.util.logging.*;

public class FraudConsumerConfigDemo {
    private static final Logger log = Logger.getLogger(FraudConsumerConfigDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FraudScorer scorer = new FraudScorer();

        Properties c = new Properties();
        c.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        c.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.GROUP_ID_CONFIG, "fraud-scoring");

        // ---- The four key configs ----
        c.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");      // 1. manual commit
        c.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");    // 2. read backlog for new group
        c.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, 50);             // 3. batch size per poll
        c.put(ConsumerConfig.MAX_POLL_INTERVAL_MS_CONFIG, 300_000);    // 4. must re-poll in 5 min

        log.info("Config: auto-commit=false (at-least-once), reset=earliest (backlog), "
               + "max.poll.records=50 (bounded batch), max.poll.interval.ms=300000 (liveness)");

        try (Consumer<String, String> consumer = new KafkaConsumer<>(c)) {
            consumer.subscribe(List.of("transactions"));
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                if (records.isEmpty()) continue;
                // At most 50 records here regardless of how many sit in the topic.
                log.info(() -> "Polled " + records.count() + " records (<= max.poll.records)");

                long startBatch = System.currentTimeMillis();
                for (ConsumerRecord<String, String> rec : records) {
                    int score = scorer.score(rec.key(), rec.value());   // slow, expensive
                    if (score > 80)
                        log.warning(() -> "HIGH fraud score " + score + " for " + rec.key());
                }
                long elapsed = System.currentTimeMillis() - startBatch;
                // Must finish and re-poll within max.poll.interval.ms or we get evicted.
                if (elapsed > 300_000)
                    log.severe("Batch took too long — risk of rebalance; lower max.poll.records");

                consumer.commitSync();   // commit AFTER scoring → at-least-once
                log.info("Committed offsets after scoring batch");
            }
        }
    }
}

