class FraudScorer {
    // Pretend-expensive scoring of a transaction for an account (Rajesh/Priya).
    int score(String account, String json) {
        // real model call would go here; simulate a small cost
        int base = json.contains("50000") ? 20 : 10;
        return base + (account.hashCode() & 0x3f);   // 0..83-ish
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
